def cal_list_gap(L):
    return [abs(L[i+1]-L[i]) for i in range(len(L)-1)]

def cal_gap_median(G):
    G = G[:] # 不改到原串列
    for i in range(len(G)): # 自寫選擇排序
        for j in range(i+1, len(G)):
            if G[j] < G[i]: G[i], G[j] = G[j], G[i]
    n = len(G)
    return G[n//2] if n % 2 else (G[n//2-1] + G[n//2]) / 2

def nearest_prime(x):
    d = 0
    while True:
        if is_prime(x - d): return x - d # 先檢查較小的，平手取小
        if is_prime(x + d): return x + d
        d += 1

def C(n, k):
    k = min(k, n - k)
    r = 1
    for i in range(k):
        r = r * (n - i) // (i + 1) # 每一步都整除
    return r
